import { registerSW } from "virtual:pwa-register";

let registered = false;

/** Registers the Workbox service worker generated by vite-plugin-pwa. */
export function registerPwa(): void {
  if (registered || typeof window === "undefined" || !("serviceWorker" in navigator)) {
    return;
  }
  registered = true;
  registerSW({
    immediate: true,
    onRegisteredSW(_url, registration) {
      if (!registration) {
        return;
      }
      // Check for a new deployment every hour while the tab stays open.
      window.setInterval(
        () => {
          void registration.update();
        },
        60 * 60 * 1000,
      );
    },
  });
}
